WITH lines AS (SELECT base.id, base.customer_id, base.created_at, base.coupon_codes, rec.product_id, rec.qty, rec.price FROM carts base LATERAL VIEW OUTER EXPLODE(base.items) t AS rec), with_windows AS (SELECT *, ROUND(price / SUM(price) OVER (PARTITION BY customer_id), 4) price_share, COUNT(price) OVER (PARTITION BY customer_id ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) price_count_1h, MAX(product_id) OVER (ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) product_id_max_30m FROM lines), base AS (SELECT *, DATE_TRUNC('YEAR', created_at) created_at_period FROM with_windows WHERE created_at > TO_DATE('2025-03-02') AND customer_id IS NOT NULL), joined AS (SELECT s.id, s.customer_id, s.created_at, s.coupon_codes, s.product_id, s.qty, s.price_count_1h, d.segment, d.country, d.signup_date FROM base s INNER JOIN customers d ON s.customer_id = d.id WHERE d.segment = 'Corporate'), metrics AS (SELECT id, customer_id, coupon_codes, price_count_1h, COUNT(qty) OVER (PARTITION BY segment, country ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) qty_count_30m, STDDEV_SAMP(product_id) OVER (PARTITION BY country) country_stddev_samp_product_id, ROUND(product_id / SUM(product_id) OVER (PARTITION BY segment), 4) product_id_share, COUNT(product_id) OVER (PARTITION BY segment ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) product_id_count_15m, ROUND(qty / SUM(qty) OVER (PARTITION BY country), 4) qty_share FROM joined) SELECT * FROM (SELECT customer_id, product_id_share, qty_share FROM metrics) src UNPIVOT INCLUDE NULLS (metric_value FOR measure IN (product_id_share, qty_share));
